function loadPrompts(goldenPath) {
  const data = JSON.parse(fs.readFileSync(goldenPath, 'utf-8'));
  // || [] -> a file missing the prompts key yields an empty run, not a .map crash.
  return (data.prompts || []).map(p => ({
    id: p.id || p.promptId,                         // accept either field name across schema versions
    prompt: p.prompt,                               // deliberately NOT defaulted — a missing prompt is a real error
    category: p.category || '',                     // default '' so later string ops never see undefined
    referenceContent: p.referenceContent || '',
  }));
}

function extractCitationIds(answer) {
  // Match the app's exact citation marker: a bracketed UUID in canonical
  // 8-4-4-4-12 hex form — specific enough that ordinary prose won't false-match.
  const matches = answer.match(
    /\[([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\]/gi
  ) || [];   // no citations -> [] -> this answer skips the browser phase entirely
  const ids = matches.map(m => m.replace(/[\[\]]/g, ''));   // strip the surrounding [ ] -> bare UUID
  return [...new Set(ids)]; // de-duplicated: a doc cited 3x is checked once, not 3 times
}

async function launchBrowser(headed) {
  const browser = await pw.chromium.launch({ headless: !headed });   // headed default OFF — only --headed for first sign-in
  let context;

  // Branch on whether a saved session exists on disk.
  if (fs.existsSync(AUTH_FILE)) {
    context = await browser.newContext({ storageState: AUTH_FILE });   // restore cookies/tokens -> no login
    console.log('  Using cached auth state');                         // log the path taken, so a stall is self-explaining
  } else {
    context = await browser.newContext();
    console.log('  No cached auth — will need login');
  }
  return { browser, context };
}

async function captureRefsFromUI(page, baseUrl, conversationId) {
  const blobRefs = [];
  await page.goto(`${baseUrl}/#/conversations/${conversationId}`, { waitUntil: 'networkidle' });

  // Broad selector to survive varied class names across the app's markup.
  // The references panel lists numbered items like "1. Best Practice Guide..."
  const refElements = await page.$$('.reference-item, [class*="reference"]');

  for (let i = 0; i < refElements.length; i++) {
    const text = (await refElements[i].textContent()) || '';
    // Narrow by CONTENT: only document-type citations should resolve to a blob;
    // skip anything that isn't a .docx/.txt (e.g. a plain link citation).
    if (!text.toLowerCase().includes('.docx') && !text.toLowerCase().includes('.txt')) continue;

    await refElements[i].click(); // open the preview
    // Scrape only anchors whose href STARTS WITH blob: — the browser mints these
    // object URLs only when a file truly loads, so their presence == real proof.
    const links = await page.$$eval('a[href^="blob:"]', els => els.map(e => e.href));
    for (const href of links) {
      blobRefs.push({ position: i + 1, refName: text.trim(), blobUrl: href });   // 1-based position maps back to the panel entry
    }
  }
  return { refCount: refElements.length, blobRefs };   // total seen vs. resolved: 'checked 0 of 3' != 'all 3 resolved'
}

async function writeExcel(results, outPath) {
  const wb = new ExcelJS.Workbook();

  // Summary tab (opens first): the key gap is cited vs. resolved.
  const ws1 = wb.addWorksheet('Summary');
  ws1.addRow(['Total prompts', results.length]);
  ws1.addRow(['Prompts with citations', results.filter(r => r.citationCount > 0).length]);       // answer CLAIMED a source
  ws1.addRow(['Prompts with blob refs (.docx/.txt)', results.filter(r => r.hasBlobRef).length]); // source actually OPENED

  // All Results tab: per-prompt drill-down.
  const ws2 = wb.addWorksheet('All Results');
  ws2.addRow(['Prompt ID', 'Citations', 'Refs in UI', 'Has Blob', 'Blob URLs']);
  for (const r of results) {
    ws2.addRow([r.promptId, r.citationCount, r.refCount, r.hasBlobRef ? 'Y' : 'N',
                r.blobRefs.map(b => b.blobUrl).join('\n')]);   // \n stacks multiple URLs within one cell
  }

  await wb.xlsx.writeFile(outPath);
}
